Module PECBAU.
Import PMU.
Abbreviation CAD := PeCLayoutU.CADDR_U.
Abbreviation EE := PeCLayoutU.EADDR_U.
(* [comment removed for export] *)

Section WithHeap.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable L : heap_layout.
Variable HI : heap_iface.
Variable P : PESK.sink_policy.
Hypothesis LY : PMU.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Hypothesis PO : PESK.sink_policy_ok P.
Let KL := PECKU.klayout_U L LY.
Let SF := PECKU.sfoot_U L LY.

(* [comment removed for export] *)
Hypothesis PEEK : PECSU.peek_spec L HI.
Hypothesis IGN : PECSU.ignore_spec L HI.
Hypothesis SRD : PECSU.src_read_spec L HI.
Hypothesis GL : PECSU.get_length_spec L HI P.
Hypothesis MKE : PECSU.make_ec_spec L HI.
Hypothesis OPN : PMU.opnew_spec L HI.
Hypothesis OPD : PMU.opdel_spec L HI.
Hypothesis VBI : PECSU.v_begin_arr_spec L HI P.
Hypothesis VBL : PECSU.v_begin_arr_len_spec L HI P.

(* [comment removed for export] *)
(* [comment removed for export] *)
Section Call.
Hypothesis SPM : PESK.sp_mode P.
Variables (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet) (LBX : list (Z * Z)) (cr : credit)
          (sp r fb cat : Z) (p : list Z) (X : st).
Variables (mo dn dp qc de rem tg vb vk : Z) (tb : PM.vstr) (stk : list PM.pstate) (str : PM.vstr) (g eg sst : Z)
          (en : PEC.enc) (k : PESK.sink) (e : bool).
Let s : PM.pst := PM.PST mo dn dp (PM.SRC qc de rem) tb tg vb vk stk.
Let sm : PM.strm := PM.STRM g eg sst.
Hypothesis HH : hi_heap HI (PEC.owned s en k ++ LBX) cr M (m_vmmaps model).
Hypothesis MOK : PMSP.model_ok model.
Hypothesis K0 : K [].
Hypothesis ENT : PMSP.entry CAD L R M sp r 7.
Hypothesis FOK : PMSP.frame_ok CAD L sp fb.
Hypothesis A10 : getr R 10%bv = Z_to_bv 64 (fb + 40).
Hypothesis A11 : getr R 11%bv = Z_to_bv 64 (fb + 432).
Hypothesis A12 : getr R 12%bv = Z_to_bv 64 (fb + 8).
Hypothesis CPRE : PEC.crun_pre RSEGS CAD EE L PMSP.T3 PMSP.T4 P M fb p X s str sm en k e cat.
Hypothesis INCS : incl (PM.vs_own str) LBX.
Hypothesis POK : PECS.payload_ok p.
Hypothesis MP : PECS.mp_run tt p X.
Hypothesis NB : s_bad (r_begin p false X) = false.
Hypothesis HB : PESK.sp_hb P (s_hi (r_begin p false X)).
Hypothesis CRED : PMSP.credit_le (PEC.pot_all L P s en k) cr.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model)
            (s' : PM.pst) (sm' : PM.strm) (en' : PEC.enc) (k' : PESK.sink) (e' : bool) (cr' : credit),
        regs_preserved R R' ->
        PEC.crun_pre RSEGS CAD EE L PMSP.T3 PMSP.T4 P M' fb p (r_begin p false X) s' str sm' en' k' e' cat ->
        PMSP.src_step (PM.p_src s) (PM.p_src s') sm sm' -> (e = true -> e' = true) ->
        L5C.hpres L LBX sp (PMSP.pm_scr 7) (PEC.W_crun CAD EE fb) M M' ->
        PMSP.credit_keep cr cr' (PEC.pot_all L P s en k) (PEC.pot_all L P s' en' k') ->
        model_but_vm model model' -> hi_heap HI (PEC.owned s' en' k' ++ LBX) cr' M' (m_vmmaps model') ->
        srealizes RSEGS SCFG (PMSP.cfg RSEGS R' r M' model') K.

(* [comment removed for export] *)
Definition CSK : list nat := [3; 4; 22; 23; 24; 25; 26; 27]%nat.
Definition csk (Ri : bvmap 5 word) : Prop := forall j, In j CSK -> getr Ri (PMK.reg j) = getr R (PMK.reg j).

(* [comment removed for export] *)
Definition saved (Mi : word -> option byte) : Prop :=
  L5.u64_at RSEGS Mi (sp - 8) (bv_unsigned (getr R (PMK.reg 1))) /\ L5.u64_at RSEGS Mi (sp - 16) (bv_unsigned (getr R (PMK.reg 8)))
  /\ L5.u64_at RSEGS Mi (sp - 24) (bv_unsigned (getr R (PMK.reg 9))) /\ L5.u64_at RSEGS Mi (sp - 32) (bv_unsigned (getr R (PMK.reg 18)))
  /\ L5.u64_at RSEGS Mi (sp - 40) (bv_unsigned (getr R (PMK.reg 19))) /\ L5.u64_at RSEGS Mi (sp - 48) (bv_unsigned (getr R (PMK.reg 20)))
  /\ L5.u64_at RSEGS Mi (sp - 56) (bv_unsigned (getr R (PMK.reg 21))).
(* [comment removed for export] *)
Definition s5m (Ri : bvmap 5 word) : Prop := getr Ri (PMK.reg 21) = Z_to_bv 64 65024.
Lemma saved_keep Mi Mj : saved Mi -> (forall a v, sp - 56 <= a -> a + 8 <= sp -> L5.u64_at RSEGS Mi a v -> L5.u64_at RSEGS Mj a v) -> saved Mj.
