Lemma call_gl (q : Z) fxi Ri Mi mdi cri si smi eni ki ei Y :
  mid fxi Ri Mi mdi cri si smi eni ki ei Y ->
  getr Ri (PMK.reg 1) = Z_to_bv 64 q -> L5.ra_ok q -> getr Ri (PMK.reg 10) = Z_to_bv 64 (fb + 40) -> getr Ri (PMK.reg 11) = Z_to_bv 64 (fb + 8) ->
  PECS.mp_gl tt p Y ->
  (forall fx2 R2 M2 md2 cr2 s2 sm2 e2, regs_preserved Ri R2 -> PECS.gl_ret p Y R2 -> mid fx2 R2 M2 md2 cr2 s2 sm2 eni ki e2 (PECS.gl_post p Y) ->
      L5C.agree_on Mi M2 (sp - 112) 48 ->
      srealizes RSEGS SCFG (PMSP.cfg RSEGS R2 q M2 md2) K) ->
  srealizes RSEGS SCFG (PMSP.cfg RSEGS Ri 0x3afac Mi mdi) K.
Proof.
