Lemma csrc_after (Wx : list L5.range) (c : Z) fxi Ri Mi mdi cri si smi eni ki ei Y fx2 R2 M2 src2 sm2 :
  mid fxi Ri Mi mdi cri si smi eni ki ei Y -> s_more Y = true -> s_done Y = false ->
  (forall a, PMK.inW Wx a -> sp - 112 <= a < sp - 56) ->
  regs_preserved Ri R2 ->
  PM.parser_at RSEGS CAD PMSP.T3 PMSP.T4 M2 (fb + 40) (fb + 512)
     (PM.PST (PM.p_more si) (PM.p_done si) (PM.p_depth si) src2 (PM.p_tb si) (PM.p_tg si) (PM.p_b si) (PM.p_k si) (PM.p_stk si)) ->
