(* [comment removed for export] *)
Lemma call_read (q kk ra : Z) fxi Ri Mi mdi cri si smi eni ki ei Y :
  mid fxi Ri Mi mdi cri si smi eni ki ei Y -> s_more Y = true -> s_done Y = false ->
  getr Ri (PMK.reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra ->
  getr Ri (PMK.reg 10) = Z_to_bv 64 (fb + 40 + 24) -> getr Ri (PMK.reg 11) = Z_to_bv 64 q -> getr Ri (PMK.reg 12) = Z_to_bv 64 kk ->
  sp - 112 <= q -> q + kk <= sp - 56 -> 1 <= kk <= 8 ->
  (forall fx2 R2 M2 si2 sm2 d, regs_preserved Ri R2 -> getr R2 (PMK.reg 10) = Z_to_bv 64 d -> 0 <= d <= kk ->
      (d < kk -> s_pos Y + d = blen p) -> s_pos Y + d <= blen p ->
      L5.bytes_at RSEGS M2 q (UbjRef.slice p (s_pos Y) d) ->
      mid fx2 R2 M2 mdi cri si2 sm2 eni ki ei (w_pos (s_pos Y + d) Y) ->
      srealizes RSEGS SCFG (PMSP.cfg RSEGS R2 ra M2 mdi) K) ->
  srealizes RSEGS SCFG (PMSP.cfg RSEGS Ri 0x3a9c0 Mi mdi) K.
Proof.
