(* [comment removed for export] *)
Lemma finish (pc v' : Z) fxi Ri Mi mdi cri si smi eni ki ei Y fx3 R3 M3 Xf :
  mid fxi Ri Mi mdi cri si smi eni ki ei Y ->
  mem_grows Mi M3 ->
  (forall i, 0 <= i < 2 ^ 64 -> ~ (fb + 40 + 8 <= i < fb + 40 + 8 + 1) -> M3 (Z_to_bv 64 i) = Mi (Z_to_bv 64 i)) ->
  msteps RSEGS (@mkst fxi Ri (Z_to_bv 64 pc) Mi (seg_rom RSEGS)) (@mkst fx3 R3 (Z_to_bv 64 0x3b7f0) M3 (seg_rom RSEGS)) ->
  L5.u8_at RSEGS M3 (fb + 40 + 8) v' -> (v' = 0 \/ v' = 1) ->
  csk R3 -> getr R3 (PMK.reg 2) = Z_to_bv 64 sp ->
  (forall j, In j [1; 8; 9; 18; 19; 20; 21]%nat -> getr R3 (PMK.reg j) = getr R (PMK.reg j)) ->
  Xf = r_begin p false X ->
  PEC.clink p Xf (PMPK.set_more si v') smi eni ki ->
  s_ec Xf = s_ec Y ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fxi Ri pc Mi mdi) K.
Proof.
