(* [comment removed for export] *)
Definition pushed (si : PM.pst) (c : PM.pstate) : PM.pst :=
  PM.PST (PM.p_more si) (PM.p_done si) (PM.p_depth si) (PM.p_src si) (PM.p_tb si) (PM.p_tg si) (PM.p_b si) (PM.p_k si) (PM.p_stk si ++ [c]).

(* [comment removed for export] *)
Lemma blocks_of_mid fxi Ri Mi mdi cri si smi eni ki ei Y :
  mid fxi Ri Mi mdi cri si smi eni ki ei Y ->
  PMFR.brange L (PEC.owned si eni ki ++ LBX)
  /\ (forall B m B' m', In (B, m) (PEC.owned si eni ki ++ LBX) -> In (B', m') (PEC.owned si eni ki ++ LBX) -> B <> B' -> B + m <= B' \/ B' + m' <= B)
  /\ NoDup (map fst (PEC.owned si eni ki ++ LBX)).
