(* [comment removed for export] *)
Lemma push_fast_C (n : Z) fxi Ri Mi mdi cri si smi eni ki ei Y :
  mid fxi Ri Mi mdi cri si smi eni ki ei Y -> s_ec Y = false ->
  Z.of_nat (length (PM.p_stk si)) < 2 ^ (PM.p_k si) ->
  getr Ri (PMK.reg 10) = Z_to_bv 64 n -> getr Ri (PMK.reg 19) = Z_to_bv 64 (fb + 40 + 24) -> 0 <= n <= 16777216 ->
  (forall fx2 R2 M2,
      mid fx2 R2 M2 mdi cri (pushed si (PEC.ps_conv (PS Marray n 0 0))) smi eni ki ei (w_stk (PS Marray n 0 0 :: s_stk Y) Y) ->
      getr R2 (PMK.reg 1) = Z_to_bv 64 0x3b7b8 -> getr R2 (PMK.reg 10) = Z_to_bv 64 (fb + 432) -> getr R2 (PMK.reg 11) = Z_to_bv 64 n ->
      getr R2 (PMK.reg 12) = Z_to_bv 64 0 -> getr R2 (PMK.reg 13) = Z_to_bv 64 (fb + 40) -> getr R2 (PMK.reg 14) = Z_to_bv 64 (fb + 8) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 0x35c3c M2 mdi) K) ->
