Lemma gworld_piece srci tbi smi eni ki ei Y Mi Mx mdx crx LBh My (Pf : Z -> Prop) (Bq nq : Z) :
  gworld srci tbi smi eni ki ei Y Mi Mx mdx crx LBh ->
  mem_grows Mx My -> (forall i, 0 <= i < 2 ^ 64 -> ~ Pf i -> My (Z_to_bv 64 i) = Mx (Z_to_bv 64 i)) ->
