    pose proof (PC fxi Ri Mi (fun j => match j with 2%nat => sp | 34%nat => vbi | 36%nat => fb + 40 | 37%nat => fb + 432 | 38%nat => fb + 8 | 48%nat => n | _ => 0 end)) as PA1;
    cbn beta iota in PA1;
    PMK.feed PA1 ltac:(first [PMK.sc | progress (unfold PEUBGP3.aligned); first [assumption | (clear; lia)] | lia ]);
