    apply (PMK.spiece RSEGS L HI KL HIok _ cri Mi mdi fxi fx1 Ri 0x3b46c R1 0xb2ef4 M1 (fun a => (sp - 160 <= a < sp - 160 + 64) \/ (sp - 96 <= a < sp - 96 + 40)) K HHi Mh Ml ltac:(lia) MS1 MG1);
