(* [comment removed for export] *)
Lemma grow_alloc_T (n ty : Z) fxi Ri Mi mdi cri moi dni dpi srci tbi tgi vbi vki stki smi eni ki ei Y :
  mid fxi Ri Mi mdi cri (PM.PST moi dni dpi srci tbi tgi vbi vki stki) smi eni ki ei Y -> s_ec Y = false ->
  Z.of_nat (length stki) = 2 ^ vki -> vki <= 10 ->
  getr Ri (PMK.reg 10) = Z_to_bv 64 n -> getr Ri (PMK.reg 19) = Z_to_bv 64 (fb + 40 + 24) -> 0 <= n <= 16777216 ->
  getr Ri (PMK.reg 20) = Z_to_bv 64 1 -> L5.u8_at RSEGS Mi (sp - 97) ty -> 0 <= ty <= 255 ->
  (forall fx1 R1 M1, mem_grows Mi M1 ->
      (forall i, 0 <= i < 2 ^ 64 -> ~ (sp - 160 <= i < sp - 160 + 64) -> ~ (sp - 96 <= i < sp - 96 + 40) -> M1 (Z_to_bv 64 i) = Mi (Z_to_bv 64 i)) ->
      (forall j, In j CSK -> getr R1 (PMK.reg j) = getr Ri (PMK.reg j)) ->
      getr R1 (PMK.reg 1) = Z_to_bv 64 0x39a90 -> getr R1 (PMK.reg 2) = Z_to_bv 64 (sp - 160) -> getr R1 (PMK.reg 8) = Z_to_bv 64 (2 ^ (vki + 1)) ->
      getr R1 (PMK.reg 9) = Z_to_bv 64 (2 ^ vki) -> getr R1 (PMK.reg 10) = Z_to_bv 64 (32 * 2 ^ (vki + 1)) -> getr R1 (PMK.reg 18) = Z_to_bv 64 (fb + 432) ->
      getr R1 (PMK.reg 19) = Z_to_bv 64 n -> getr R1 (PMK.reg 20) = Z_to_bv 64 (fb + 40 + 360) ->
      L5.u64_at RSEGS M1 (sp - 160) (sp - 96) -> L5.u64_at RSEGS M1 (sp - 152) 0x398ac -> L5.u64_at RSEGS M1 (sp - 64) (fb + 40 + 360) ->
      L5.u64_at RSEGS M1 (sp - 72) 0 -> L5.u64_at RSEGS M1 (sp - 136) (fb + 8) -> L5.u64_at RSEGS M1 (sp - 128) (fb + 40) ->
      L5.u64_at RSEGS M1 (sp - 120) 0x3b72c -> L5.u8_at RSEGS M1 (sp - 97) ty ->
      hi_heap HI (PEC.owned (PM.PST moi dni dpi srci tbi tgi vbi vki stki) eni ki ++ LBX) cri M1 (m_vmmaps mdi) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0xb2f40 M1 mdi) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fxi Ri 0x3b45c Mi mdi) K.
Proof.
Local Ltac galloct PC fxi Ri Mi mdi cri K sp fb vbi n ty STK HHi Mh Ml KX X9 X18 :=
    pose proof (PC fxi Ri Mi (fun j => match j with 2%nat => sp | 34%nat => vbi | 36%nat => fb + 40 | 37%nat => fb + 432 | 38%nat => fb + 8 | 48%nat => n | 50%nat => ty | _ => 0 end)) as PA1;
    cbn beta iota in PA1;
    PMK.feed PA1 ltac:(first [PMK.sc | progress (unfold PEUBGP3.aligned); first [assumption | (clear; lia)] | lia ]);
    destruct PA1 as (fx1 & R1 & M1 & MG1 & _ & FRZ1 & MS1 & KS1 & Y1 & Y2 & Y8 & Y9 & Y10 & Y11 & Y12 & Y13 & Y14 & Y19 & Y20 & C160 & C152 & C64 & C72 & C136 & C128 & C120 & C97);
    apply (PMK.spiece RSEGS L HI KL HIok _ cri Mi mdi fxi fx1 Ri 0x3b404 R1 0xb2ef4 M1 (fun a => (sp - 160 <= a < sp - 160 + 64) \/ (sp - 96 <= a < sp - 96 + 40)) K HHi Mh Ml ltac:(lia) MS1 MG1);
    [ intros a Ha N; apply FRZ1; [exact Ha| intros HX; apply N; left; exact HX| intros HX; apply N; right; exact HX]
    | intros a Pa; apply (PMK.cwr_stack L _ Mi sp 26624 a STK); lia
    | intros a; apply PMK.or_dec; apply PMK.rng_dec
    | intros HH1; apply (KX fx1 R1 M1 MG1);
      [ intros i Hi N1 N2; apply FRZ1; [exact Hi| exact N1| exact N2]
      | intros j Hj; apply KS1; clear - Hj; cbn in Hj; decompose [or] Hj; subst; first [PMK.inl | contradiction]
      | exact Y1 | exact Y2 | PMK.greg | PMK.greg | PMK.greg | rewrite (KS1 18%nat) by PMK.inl; exact X18
