Lemma sub_I fx2 R2 M2 si2 sm2 (c : Z) :
  s_depth X + 1 <= MAX_DEPTH ->
  mid fx2 R2 M2 model cr si2 sm2 en k e (PECBD.X1 X) -> s_pos X < blen p -> bat p (s_pos X) = c -> c <> 36 -> c <> 35 ->
